/**
 * Eliza API Client
 *
 * A TypeScript client for the Eliza API (Yandex's internal Anthropic proxy).
 * Provides methods for checking quota, usage, and selecting the best token
 * based on remaining balance.
 */
import createLogger from "@yandex-int/yandex-logger";
const logger = createLogger({ name: "eliza-cli" });
// ============================================================================
// Error Classes
// ============================================================================
export class ElizaApiError extends Error {
    statusCode;
    responseBody;
    constructor(message, statusCode, responseBody) {
        super(message);
        this.statusCode = statusCode;
        this.responseBody = responseBody;
        this.name = "ElizaApiError";
    }
}
export class ElizaNetworkError extends Error {
    cause;
    constructor(message, cause) {
        super(message);
        this.cause = cause;
        this.name = "ElizaNetworkError";
    }
}
export class ElizaTimeoutError extends Error {
    timeout;
    endpoint;
    constructor(timeout, endpoint) {
        super(`Request to ${endpoint} timed out after ${timeout}ms`);
        this.timeout = timeout;
        this.endpoint = endpoint;
        this.name = "ElizaTimeoutError";
    }
}
export class NoAvailableTokensError extends Error {
    constructor(message) {
        super(message);
        this.name = "NoAvailableTokensError";
    }
}
// ============================================================================
// Main Client Class
// ============================================================================
export class ElizaClient {
    baseUrl;
    timeout;
    constructor(config = {}) {
        this.baseUrl = config.baseUrl ?? "https://api.eliza.yandex.net";
        this.timeout = config.timeout ?? 10000;
    }
    /**
     * Get quota information for a token.
     * @param token - The API token to check
     * @param poolName - Optional pool name for Ya-Pool header (uses pool quota instead of personal)
     * @returns Quota response with nested quota data
     */
    async getQuota(token, poolName) {
        return this.request("/quota", token, { poolName });
    }
    /**
     * Get usage information for a token.
     * @param token - The API token to check
     * @param poolName - Optional pool name for Ya-Pool header (uses pool quota instead of personal)
     * @returns Usage response with nested usage data
     */
    async getUsage(token, poolName) {
        return this.request("/usage", token, { poolName });
    }
    /**
     * Delete the daily quota bucket for the current token.
     * @param token - The API token to delete daily quota for
     * @param poolName - Optional pool name for Ya-Pool header
     */
    async deleteDailyQuota(token, poolName) {
        await this.request("/v2/quotas/daily/all", token, {
            method: "DELETE",
            poolName,
            authScheme: "oauth",
            parseJson: false,
        });
    }
    /**
     * Get pool configuration and access information.
     * @param token - OAuth token
     * @param poolId - Pool identifier
     */
    async getPool(token, poolId) {
        return this.request(`/pools/${encodeURIComponent(poolId)}`, token, { authScheme: "oauth" });
    }
    /**
     * Create or update a pool. Updates must include the full desired members list.
     * @param token - OAuth token
     * @param poolId - Pool identifier
     * @param payload - Pool ABC slug and full member list
     */
    async setPool(token, poolId, payload) {
        return this.request(`/pools/${encodeURIComponent(poolId)}`, token, {
            method: "PUT",
            authScheme: "oauth",
            body: payload,
        });
    }
    /**
     * Delete a pool.
     * @param token - OAuth token
     * @param poolId - Pool identifier
     */
    async deletePool(token, poolId) {
        await this.request(`/pools/${encodeURIComponent(poolId)}`, token, {
            method: "DELETE",
            authScheme: "oauth",
            parseJson: false,
        });
    }
    /**
     * Calculate the remaining balance for a token.
     * @param token - The API token value
     * @param tokenKey - The key identifier for the token (from SecretRef.key)
     * @param poolName - Optional pool name for Ya-Pool header (uses pool quota instead of personal)
     * @returns TokenBalance with remaining quotas and effective balance
     */
    async getBalance(token, tokenKey, poolName) {
        const [quotaResponse, usageResponse] = await Promise.all([
            this.getQuota(token, poolName),
            this.getUsage(token, poolName),
        ]);
        // Validate quota response structure (data is nested in quota.quota)
        const quota = quotaResponse?.quota;
        if (!quota || !quota.all || !quota.all.daily || !quota.all.monthly) {
            throw new ElizaApiError(`Invalid quota response structure for token ${tokenKey}. Expected {quota: {all: {daily: {...}, monthly: {...}}}}, got: ${JSON.stringify(quotaResponse)}`, 500, JSON.stringify(quotaResponse));
        }
        // Validate usage response structure (data is nested in usage.usage)
        const usage = usageResponse?.usage;
        if (!usage || !usage.all || !usage.all.daily || !usage.all.monthly) {
            throw new ElizaApiError(`Invalid usage response structure for token ${tokenKey}. Expected {usage: {all: {daily: {...}, monthly: {...}}}}, got: ${JSON.stringify(usageResponse)}`, 500, JSON.stringify(usageResponse));
        }
        // Prefer model-specific "claude" quota/usage if available, fall back to "all"
        const quotaBucket = this.selectQuotaBucket(quota, "claude");
        const usageBucket = this.selectUsageBucket(usage, "claude");
        // Calculate remaining for daily and monthly
        // -1 in quota means unlimited, which we represent as null
        const dailyRemaining = this.calculateRemaining(quotaBucket.daily.cost, usageBucket.daily.cost);
        const monthlyRemaining = this.calculateRemaining(quotaBucket.monthly.cost, usageBucket.monthly.cost);
        // Calculate effective balance for sorting
        const effectiveBalance = this.calculateEffectiveBalance(dailyRemaining, monthlyRemaining);
        return {
            tokenKey,
            poolName,
            dailyRemaining,
            monthlyRemaining,
            effectiveBalance,
        };
    }
    /**
     * Select the best token from a list based on remaining balance.
     * Tokens are sorted by effective balance (highest first).
     *
     * @param tokens - Array of token objects with token value, key identifier, and optional pool name
     * @returns The selected token, pool name (if any), and its balance information
     * @throws NoAvailableTokensError if no tokens have remaining balance
     */
    async selectBestToken(tokens) {
        if (tokens.length === 0) {
            throw new NoAvailableTokensError("No API tokens provided");
        }
        if (tokens.length === 1) {
            // Single token - just get its balance and return
            const { token, tokenKey, poolName } = tokens[0];
            const balance = await this.getBalance(token, tokenKey, poolName);
            const poolInfo = poolName ? ` (pool: ${poolName})` : "";
            logger.info(`Single token provided (${tokenKey}${poolInfo}), balance: daily=${balance.dailyRemaining}, monthly=${balance.monthlyRemaining}`);
            return { token, poolName, balance };
        }
        // Multiple tokens - check balances concurrently
        logger.info(`Checking balances for ${tokens.length} tokens...`);
        const balanceResults = await Promise.all(tokens.map(async ({ token, tokenKey, poolName }) => {
            try {
                const balance = await this.getBalance(token, tokenKey, poolName);
                return { token, poolName, balance, success: true };
            }
            catch (error) {
                const errorMessage = error instanceof Error ? error.message : String(error);
                logger.warn(`Failed to get balance for token ${tokenKey}: ${errorMessage}`);
                return {
                    token,
                    poolName,
                    balance: {
                        tokenKey,
                        poolName,
                        dailyRemaining: null,
                        monthlyRemaining: null,
                        effectiveBalance: -Infinity,
                    },
                    success: false,
                    error: errorMessage,
                };
            }
        }));
        // Filter to successful results only
        const successfulResults = balanceResults.filter((r) => r.success);
        if (successfulResults.length === 0) {
            const errors = balanceResults
                .map((r) => `${r.balance.tokenKey}: ${r.error}`)
                .join("; ");
            throw new NoAvailableTokensError(`All tokens failed balance check: ${errors}`);
        }
        // Filter out tokens with zero or negative balance
        const availableResults = successfulResults.filter((r) => r.balance.effectiveBalance > 0);
        if (availableResults.length === 0) {
            const balances = successfulResults
                .map((r) => `${r.balance.tokenKey}: daily=${r.balance.dailyRemaining}, monthly=${r.balance.monthlyRemaining}`)
                .join("; ");
            throw new NoAvailableTokensError(`All tokens have exhausted quota: ${balances}`);
        }
        // Sort by effective balance (highest first)
        availableResults.sort((a, b) => b.balance.effectiveBalance - a.balance.effectiveBalance);
        const selected = availableResults[0];
        const poolInfo = selected.poolName
            ? ` (pool: ${selected.poolName})`
            : "";
        logger.info(`Selected token ${selected.balance.tokenKey}${poolInfo} with balance: ` +
            `daily=${selected.balance.dailyRemaining}, monthly=${selected.balance.monthlyRemaining}, ` +
            `effective=${selected.balance.effectiveBalance.toFixed(2)}`);
        // Log other available tokens
        if (availableResults.length > 1) {
            const others = availableResults
                .slice(1)
                .map((r) => `${r.balance.tokenKey}: ${r.balance.effectiveBalance.toFixed(2)}`)
                .join(", ");
            logger.info(`Other available tokens: ${others}`);
        }
        return {
            token: selected.token,
            poolName: selected.poolName,
            balance: selected.balance,
        };
    }
    /**
     * Select the best token from a list, excluding specified token keys.
     * Used for token rotation on 429/quota errors — excludes already-exhausted tokens.
     *
     * @param tokens - Array of token objects with token value, key identifier, and optional pool name
     * @param excludeTokenKeys - Set of token keys to exclude from selection
     * @returns The selected token and balance info, or null if no tokens available after exclusion
     */
    async selectBestTokenExcluding(tokens, excludeTokenKeys) {
        const filtered = tokens.filter((t) => !excludeTokenKeys.has(t.tokenKey));
        if (filtered.length === 0) {
            logger.info(`No tokens remaining after excluding ${excludeTokenKeys.size} token(s)`);
            return null;
        }
        try {
            return await this.selectBestToken(filtered);
        }
        catch (error) {
            if (error instanceof NoAvailableTokensError) {
                logger.warn(`No available tokens after exclusion: ${error.message}`);
                return null;
            }
            throw error;
        }
    }
    // ========================================================================
    // Private Methods
    // ========================================================================
    /**
     * Select the best quota bucket: prefer a model-specific bucket (e.g. "claude") if it exists
     * with valid daily/monthly entries, otherwise fall back to "all".
     */
    selectQuotaBucket(data, preferredModel) {
        const preferred = data[preferredModel];
        if (preferred?.daily && preferred?.monthly) {
            return preferred;
        }
        return data.all;
    }
    /**
     * Select the best usage bucket: prefer a model-specific bucket (e.g. "claude") if it exists
     * with valid daily/monthly entries, otherwise fall back to "all".
     */
    selectUsageBucket(data, preferredModel) {
        const preferred = data[preferredModel];
        if (preferred?.daily && preferred?.monthly) {
            return preferred;
        }
        return data.all;
    }
    /**
     * Calculate remaining quota.
     * @param quota - The quota limit (-1 = unlimited)
     * @param usage - Current usage
     * @returns Remaining amount (null = unlimited)
     */
    calculateRemaining(quota, usage) {
        if (quota === -1) {
            return null; // Unlimited
        }
        return Math.max(0, quota - usage);
    }
    /**
     * Calculate effective balance for sorting.
     * Uses the most limiting factor (lowest non-null limit).
     * Returns Infinity if all limits are unlimited.
     */
    calculateEffectiveBalance(dailyRemaining, monthlyRemaining) {
        const values = [];
        if (dailyRemaining !== null) {
            values.push(dailyRemaining);
        }
        if (monthlyRemaining !== null) {
            values.push(monthlyRemaining);
        }
        if (values.length === 0) {
            // All unlimited
            return Infinity;
        }
        // Return the minimum (most limiting)
        return Math.min(...values);
    }
    /**
     * Make an HTTP request to the Eliza API.
     * @param path - The API endpoint path
     * @param token - The API token for authentication
     * @param options - Request options
     */
    async request(path, token, options = {}) {
        const { method = "GET", poolName, authScheme = "api-key", parseJson = true, body, } = options;
        const url = `${this.baseUrl}${path}`;
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);
        try {
            const headers = authScheme === "oauth"
                ? { Authorization: `OAuth ${token}` }
                : { "x-api-key": token };
            // Add Ya-Pool header if pool name is provided
            if (poolName) {
                headers["Ya-Pool"] = poolName;
            }
            if (body !== undefined) {
                headers["Content-Type"] = "application/json";
            }
            const response = await fetch(url, {
                method,
                headers,
                ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
                signal: controller.signal,
            });
            if (!response.ok) {
                const body = await response.text();
                throw new ElizaApiError(`Eliza API error at ${path}: ${response.status} ${response.statusText}`, response.status, body);
            }
            if (!parseJson) {
                return undefined;
            }
            return (await response.json());
        }
        catch (error) {
            if (error instanceof ElizaApiError) {
                throw error;
            }
            if (error instanceof Error && error.name === "AbortError") {
                throw new ElizaTimeoutError(this.timeout, path);
            }
            throw new ElizaNetworkError(`Network error during ${method} ${path}: ${error instanceof Error ? error.message : String(error)}`, error instanceof Error ? error : undefined);
        }
        finally {
            clearTimeout(timeoutId);
        }
    }
}
